package vn.eventplatform.ad.service;

import lombok.RequiredArgsConstructor;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vn.eventplatform.ad.domain.*;
import vn.eventplatform.ad.dto.*;
import vn.eventplatform.ad.enums.*;
import vn.eventplatform.ad.mapper.AdMapper;
import vn.eventplatform.ad.repository.*;
import vn.eventplatform.common.dto.ErrorCode;
import vn.eventplatform.common.exception.AppException;
import java.math.*;
import java.time.*;
import java.util.*;
import java.util.stream.Collectors;

@Service @RequiredArgsConstructor
public class AdService {
    private final AdPackageRepository packages; private final AdCampaignRepository campaigns; private final BannerRepository banners; private final AdPositionPriceRepository positionPrices; private final CampaignPositionRepository campaignPositions; private final AdBillRepository bills; private final AdMapper mapper;
    public Responses.PackageResponse packageCreate(Requests.PackageRequest r) { AdPackage p=new AdPackage(); p.setName(r.name());p.setDescription(r.description());p.setPrice(r.price());p.setDurationDays(r.durationDays());p.setActive(r.active()==null||r.active());return pkg(packages.save(p)); }
    public List<Responses.PackageResponse> packageAll() { return packages.findAll().stream().map(this::pkg).toList(); }
    public Responses.PackageResponse packageUpdate(UUID id,Requests.PackageRequest r) { AdPackage p=packageById(id);p.setName(r.name());p.setDescription(r.description());p.setPrice(r.price());p.setDurationDays(r.durationDays());if(r.active()!=null)p.setActive(r.active());return pkg(packages.save(p)); }
    public void packageDelete(UUID id) { packages.delete(packageById(id)); }
    public Responses.PositionPriceResponse positionPriceCreate(Requests.PositionPriceRequest r) { if(positionPrices.findByPosition(r.position()).isPresent())throw bad("Position đã có cấu hình phụ phí"); AdPositionPrice p=new AdPositionPrice();p.setPosition(r.position());p.setBonusPrice(r.bonusPrice());p.setActive(r.active()==null||r.active());return positionPrice(positionPrices.save(p)); }
    public List<Responses.PositionPriceResponse> positionPrices(boolean activeOnly) { return (activeOnly?positionPrices.findByActiveTrueOrderByPositionAsc():positionPrices.findAll()).stream().map(this::positionPrice).toList(); }
    public Responses.PositionPriceResponse positionPriceUpdate(UUID id,Requests.PositionPriceRequest r) { AdPositionPrice p=positionPriceById(id);positionPrices.findByPosition(r.position()).filter(other->!other.getId().equals(id)).ifPresent(other->{throw bad("Position đã có cấu hình phụ phí");});p.setPosition(r.position());p.setBonusPrice(r.bonusPrice());if(r.active()!=null)p.setActive(r.active());return positionPrice(positionPrices.save(p)); }
    public void positionPriceDelete(UUID id) { positionPrices.delete(positionPriceById(id)); }
    @Transactional public Responses.CampaignResponse register(UUID organizer,Requests.CampaignRequest r) { AdPackage p=packageById(r.packageId());if(!p.getActive())throw bad("Gói quảng cáo không hoạt động");if(!r.endsAt().isAfter(r.startsAt()))throw bad("Thời gian campaign không hợp lệ");if(new HashSet<>(r.positions()).size()!=r.positions().size())throw bad("Danh sách position không được trùng lặp");List<AdPositionPrice> prices=r.positions().stream().map(position->positionPrices.findByPosition(position).filter(AdPositionPrice::getActive).orElseThrow(()->bad("Position không hoạt động hoặc chưa được cấu hình: "+position))).toList();BigDecimal total=p.getPrice().add(prices.stream().map(AdPositionPrice::getBonusPrice).reduce(BigDecimal.ZERO,BigDecimal::add));AdCampaign c=new AdCampaign();c.setOrganizerId(organizer);c.setAdPackage(p);c.setName(r.name());c.setPricingMode(r.pricingMode());c.setStartsAt(r.startsAt());c.setEndsAt(r.endsAt());c.setPackagePrice(p.getPrice());c.setTotalPrice(total);c.setEscrowAmount(r.pricingMode()==PricingMode.POSTPAID_ESCROW?total:BigDecimal.ZERO);c.setFeeAmount(r.pricingMode()==PricingMode.PREPAID?total:BigDecimal.ZERO);c=campaigns.save(c);for(AdPositionPrice price:prices){CampaignPosition snapshot=new CampaignPosition();snapshot.setCampaign(c);snapshot.setPosition(price.getPosition());snapshot.setBonusPrice(price.getBonusPrice());campaignPositions.save(snapshot);}if(c.getPricingMode()==PricingMode.PREPAID)createBill(c,c.getFeeAmount(),AdBillStatus.PAID,Instant.now());return camp(c); }
    public List<Responses.CampaignResponse> organizerCampaigns(UUID id) { return campaigns.findByOrganizerId(id).stream().map(this::camp).toList(); }
    @Transactional public Responses.CampaignResponse approve(UUID id) { AdCampaign c=campaign(id);c.setStatus(CampaignStatus.APPROVED);c.setRejectionReason(null);return camp(campaigns.save(c)); }
    @Transactional public Responses.CampaignResponse reject(UUID id,String reason) { AdCampaign c=campaign(id);c.setStatus(CampaignStatus.REJECTED);c.setRejectionReason(reason);return camp(campaigns.save(c)); }
    public BigDecimal postpaidFee(UUID id) { AdCampaign c=campaign(id);if(c.getPricingMode()!=PricingMode.POSTPAID_ESCROW)throw bad("Campaign không phải POSTPAID_ESCROW");return c.getTotalPrice(); }
    @Transactional public void publishSettlement(UUID id) { AdCampaign c=campaign(id);if(c.getPricingMode()!=PricingMode.POSTPAID_ESCROW)throw bad("Campaign không phải POSTPAID_ESCROW");c.setFeeAmount(c.getTotalPrice());c.setSettlementPublished(true);c=campaigns.save(c);if(bills.findByCampaignId(c.getId()).isEmpty())createBill(c,c.getFeeAmount(),AdBillStatus.PENDING_PAYMENT,null); }
    @Transactional(readOnly=true) public List<Responses.BillResponse> organizerBills(UUID organizerId){return bills.findByOrganizerIdOrderByCreatedAtDesc(organizerId).stream().map(mapper::toBillResponse).toList();}
    @Transactional(readOnly=true) public Responses.BillResponse organizerBill(UUID organizerId,UUID billId){AdBill bill=bill(billId);if(!bill.getOrganizerId().equals(organizerId))throw new AccessDeniedException("Bạn không có quyền xem hóa đơn này");return mapper.toBillResponse(bill);}
    @Transactional(readOnly=true) public List<Responses.BillResponse> allBills(){return bills.findAllByOrderByCreatedAtDesc().stream().map(mapper::toBillResponse).toList();}
    @Transactional(readOnly=true) public AdRevenueResponse revenue(){List<AdBill> all=bills.findAll();BigDecimal total=all.stream().map(AdBill::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal collected=all.stream().filter(b->b.getStatus()==AdBillStatus.PAID).map(AdBill::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);long paid=all.stream().filter(b->b.getStatus()==AdBillStatus.PAID).count();return new AdRevenueResponse(total,collected,total.subtract(collected),all.size(),paid,all.size()-paid);}
    @Transactional public Responses.BannerResponse banner(Requests.BannerRequest r) { Banner b=new Banner();fill(b,r);return ban(banners.save(b)); }
    @Transactional public Responses.BannerResponse bannerUpdate(UUID id,Requests.BannerRequest r) { Banner b=banner(id);fill(b,r);return ban(banners.save(b)); }
    @Transactional public Responses.BannerResponse requestImageChange(UUID id,String url) { Banner b=banner(id);b.setPendingImageUrl(url);return ban(banners.save(b)); }
    @Transactional public Responses.BannerResponse approveImage(UUID id) { Banner b=banner(id);if(b.getPendingImageUrl()==null)throw bad("Không có ảnh chờ duyệt");b.setImageUrl(b.getPendingImageUrl());b.setPendingImageUrl(null);return ban(banners.save(b)); }
    public Responses.PublicBannersResponse publicBanners() { Map<BannerPosition,List<Responses.BannerResponse>> grouped=banners.findPublic(LocalDateTime.now()).stream().map(this::ban).collect(Collectors.groupingBy(Responses.BannerResponse::position,()->new EnumMap<>(BannerPosition.class),Collectors.toList()));return new Responses.PublicBannersResponse(grouped); }
    public void deleteBanner(UUID id) { banners.delete(banner(id)); }
    private void fill(Banner b,Requests.BannerRequest r) { if(!r.endsAt().isAfter(r.startsAt()))throw bad("Thời gian banner không hợp lệ");AdCampaign c=campaign(r.campaignId());if(!campaignPositions.existsByCampaignIdAndPosition(c.getId(),r.position()))throw bad("Position banner không thuộc các position đã đăng ký của campaign");b.setCampaign(c);if(r.imageUrl()!=null)b.setImageUrl(r.imageUrl());if(b.getImageUrl()==null)throw bad("Thiếu ảnh banner");b.setPosition(r.position());b.setPriority(Optional.ofNullable(r.priority()).orElse(0));b.setStartsAt(r.startsAt());b.setEndsAt(r.endsAt());b.setActive(r.active()==null||r.active()); }
    private void createBill(AdCampaign c,BigDecimal amount,AdBillStatus status,Instant paidAt){AdBill bill=new AdBill();bill.setBillCode("AD-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());bill.setOrganizerId(c.getOrganizerId());bill.setCampaign(c);bill.setAmount(amount);bill.setStatus(status);bill.setPaidAt(paidAt);bills.save(bill);} private AdPackage packageById(UUID id){return packages.findById(id).orElseThrow(()->new AppException(ErrorCode.RESOURCE_NOT_FOUND,"Không tìm thấy gói"));} private AdPositionPrice positionPriceById(UUID id){return positionPrices.findById(id).orElseThrow(()->new AppException(ErrorCode.RESOURCE_NOT_FOUND,"Không tìm thấy cấu hình position"));} private AdCampaign campaign(UUID id){return campaigns.findById(id).orElseThrow(()->new AppException(ErrorCode.RESOURCE_NOT_FOUND,"Không tìm thấy campaign"));} private AdBill bill(UUID id){return bills.findById(id).orElseThrow(()->new AppException(ErrorCode.RESOURCE_NOT_FOUND,"Không tìm thấy hóa đơn quảng cáo"));} private Banner banner(UUID id){return banners.findById(id).orElseThrow(()->new AppException(ErrorCode.RESOURCE_NOT_FOUND,"Không tìm thấy banner"));} private AppException bad(String m){return new AppException(ErrorCode.BAD_REQUEST,m);}
    private Responses.PackageResponse pkg(AdPackage p){return mapper.toPackageResponse(p);} private Responses.PositionPriceResponse positionPrice(AdPositionPrice p){return new Responses.PositionPriceResponse(p.getId(),p.getPosition(),p.getBonusPrice(),p.getActive());} private Responses.CampaignResponse camp(AdCampaign c){List<Responses.CampaignPositionResponse> ps=campaignPositions.findByCampaignId(c.getId()).stream().map(p->new Responses.CampaignPositionResponse(p.getPosition(),p.getBonusPrice())).toList();return new Responses.CampaignResponse(c.getId(),c.getOrganizerId(),c.getAdPackage().getId(),c.getName(),c.getPricingMode(),c.getStatus(),c.getPackagePrice(),ps,c.getTotalPrice(),c.getFeeAmount(),c.getEscrowAmount(),c.getSettlementPublished(),c.getRejectionReason());} private Responses.BannerResponse ban(Banner b){return mapper.toBannerResponse(b);}
}
